#include <WiFi.h>
#include <BLEDevice.h>
#include <BLEUtils.h>
#include <BLEServer.h>

// Пин кнопки
const int buttonPin = 4;

// Флаги состояния
bool isJamming = false;

// Переменные для таймеров
unsigned long wifiLastSwitch = 250;
unsigned long bleLastUpdate = 250;

// Случайные значения для задержек (будут генерироваться при включении)
unsigned long wifiDelayMin = 200;
unsigned long wifiDelayMax = 300;
unsigned long bleDelayMin = 250;
unsigned long bleDelayMax = 350;

void setup() {
  Serial.begin(115200);

  pinMode(buttonPin, INPUT_PULLUP);

  Serial.println("ESP32-S3 Jammer Ready");
  Serial.println("GPIO 4: Вкл/Выкл глушилку");

  // Начальное состояние
  WiFi.mode(WIFI_OFF);
  BLEDevice::init("");
}

void loop() {
  // Чтение кнопки с антидребезгом
  if (digitalRead(buttonPin) == LOW) {
    delay(200); // Дребезг
    if (digitalRead(buttonPin) == LOW) {
      isJamming = !isJamming;

      if (isJamming) {
        startJamming();
      } else {
        stopJamming();
      }

      // Ждем отпускания кнопки
      while (digitalRead(buttonPin) == LOW) {
        delay(10);
      }
    }
  }

  if (isJamming) {
    jamWifi();
    jamBLE();
  }
}

void startJamming() {
  Serial.println(">>> ГЛУШИЛКА ВКЛЮЧЕНА <<<");

  // Генерируем случайные интервалы при включении
  wifiDelayMin = 200; wifiDelayMax = 300;
  bleDelayMin = 250; bleDelayMax = 350;

  // Инициализация Wi-Fi для глушения
  WiFi.disconnect(false);
  WiFi.mode(WIFI_STA);
  WiFi.setOutputPower(20.0); // Максимальная мощность

  // Инициализация BLE
  BLEDevice::init("ESP32-Jammer");
}

void stopJamming() {
  Serial.println("<<< ГЛУШИЛКА ВЫКЛЮЧЕНА <<<");

  WiFi.mode(WIFI_OFF);
  BLEDevice::deinit(true);
}

// --- Глушение Wi-Fi ---
void jamWifi() {
  unsigned long currentMillis = millis();

  // Проверяем, прошло ли нужное время для переключения канала
  if (currentMillis - wifiLastSwitch >= random(wifiDelayMin, wifiDelayMax + 1)) {
    wifiLastSwitch = currentMillis;

    // Переключаем канал (1-13)
    uint8_t channel = random(1, 14);

    // Меняем канал
    // Примечание: WiFi.setChannel() меняет текущий канал передатчика
    WiFi.setChannel(channel);

    // Генерируем шум: отправляем пустой пакет или сканируем
    // Это создает радиошум на этом канале
    WiFi.scanNetworks(false); // Асинхронное сканирование создает помехи

    // Или можно просто держать канал занятым
    // WiFi.begin(); 
  }
}

// --- Глушение Bluetooth ---
void jamBLE() {
  unsigned long currentMillis = millis();

  // Проверяем, прошло ли нужное время для отправки пакета BLE
  if (currentMillis - bleLastUpdate >= random(bleDelayMin, bleDelayMax + 1)) {
    bleLastUpdate = currentMillis;

    // Создаем случайный advertising packet
    // Это "забивает" эфир BLE пакетами

    BLEAdvertising *pAdvertising = BLEDevice::getAdvertising();

    // Генерируем случайный адрес или данные
    // Отправляем рекламный пакет с высокой мощностью
    pAdvertising->setAdvType(ADV_TYPE_NONCONN_IND);
    pAdvertising->addServiceUUID(UUID(0x180A)); // Simple service
    pAdvertising->setAdvData("JAMMING"); // Данные для рекламы

    // Начинаем рекламу
    BLEDevice::getServer()->startAdvertising();

    // Останавливаем сразу, чтобы создать импульс помехи
    // Или оставляем включенным, если нужно постоянное присутствие
    // BLEDevice::getServer()->stopAdvertising(); 
  }
}
